package com.yuegang.zhihui.system.application;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.system.api.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;
public final class SystemCatalogService{private final JdbcTemplate jdbc;public SystemCatalogService(DataSource d){jdbc=new JdbcTemplate(d);}public List<DictionaryView>dictionaries(){return jdbc.query("SELECT code,name FROM system_dictionary_type WHERE enabled=TRUE ORDER BY code",(t,n)->new DictionaryView(t.getString(1),t.getString(2),jdbc.query("SELECT item_key,item_value,sort_order FROM system_dictionary_item i JOIN system_dictionary_type t ON t.id=i.type_id WHERE t.code=? AND i.enabled=TRUE ORDER BY i.sort_order,i.item_key",(i,x)->new DictionaryView.Item(i.getString(1),i.getString(2),i.getInt(3)),t.getString(1))));}public List<FeatureFlagView>flags(){return jdbc.query("SELECT flag_key,enabled,rollout_percent,rules_json,version FROM system_feature_flag ORDER BY flag_key",(r,n)->view(r));}public FeatureFlagView updateFlag(String key,UpdateFeatureFlagRequest c,long operator){if(!key.matches("[a-z][a-z0-9._-]{1,127}"))throw new BusinessException(ErrorCode.VALIDATION_ERROR);int n=c.version()==0?jdbc.update("INSERT INTO system_feature_flag(flag_key,enabled,rollout_percent,rules_json,updated_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),rollout_percent=VALUES(rollout_percent),rules_json=VALUES(rules_json),updated_by=VALUES(updated_by),version=version+1",key,c.enabled(),c.rolloutPercent(),c.rulesJson(),operator):jdbc.update("UPDATE system_feature_flag SET enabled=?,rollout_percent=?,rules_json=?,updated_by=?,version=version+1 WHERE flag_key=? AND version=?",c.enabled(),c.rolloutPercent(),c.rulesJson(),operator,key,c.version());if(n<1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return jdbc.query("SELECT flag_key,enabled,rollout_percent,rules_json,version FROM system_feature_flag WHERE flag_key=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return view(r);},key);}private static FeatureFlagView view(java.sql.ResultSet r)throws java.sql.SQLException{return new FeatureFlagView(r.getString(1),r.getBoolean(2),r.getInt(3),r.getString(4),r.getLong(5));}}
